def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    threshold = 200000
    exceeds = [v1 > threshold, v2 > threshold]
    value = sum(exceeds)
    return {
        "value": value,
        "trace": {
            "threshold": threshold,
            "exceeds_by_year": exceeds,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "count"
            }
        }
    }
